use std::fs
use std::collections::HashMap

fn all_digits(s: string) -> bool {
    if s.len() == 0 {
        return false
    }
    for c in s.chars() {
        if c < '0' || c > '9' {
            return false
        }
    }
    true
}

fn main() {
    let text = fs::read_to_string("/dev/stdin").unwrap_or("")
    let mut totals: HashMap<string, int> = HashMap::new()
    let mut counts: HashMap<string, int> = HashMap::new()
    let mut actions: HashMap<string, int> = HashMap::new()
    let mut users: Vec<string> = []
    let mut bad = 0
    for line in text.lines() {
        let parts: Vec<string> = line.split_whitespace().map(|p| p.to_string()).collect()
        if parts.len() != 3 || !all_digits(parts[2]) {
            bad += 1
            continue
        }
        let u = parts[0]
        let a = parts[1]
        let n: int = parts[2].parse::<int>().unwrap_or(0)
        if !totals.contains_key(u) {
            users.push(u)
            totals.insert(u, 0)
            counts.insert(u, 0)
        }
        totals.insert(u, totals.get(u).unwrap_or(0) + n)
        counts.insert(u, counts.get(u).unwrap_or(0) + 1)
        let key = u + " " + a
        actions.insert(key, actions.get(key).unwrap_or(0) + 1)
    }
    users.sort_by(|x, y| {
        let tx = totals.get(x).unwrap_or(0)
        let ty = totals.get(y).unwrap_or(0)
        if tx != ty {
            ty.cmp(tx)
        } else {
            x.cmp(y)
        }
    })
    for u in users {
        let mut best = ""
        let mut bc = 0
        for line in text.lines() {
            let parts: Vec<string> = line.split_whitespace().map(|p| p.to_string()).collect()
            if parts.len() == 3 && parts[0] == u && all_digits(parts[2]) {
                let c = actions.get(u + " " + parts[1]).unwrap_or(0)
                if c > bc || (c == bc && parts[1] < best) {
                    bc = c
                    best = parts[1]
                }
            }
        }
        println("${u} ${counts.get(u).unwrap_or(0)} ${totals.get(u).unwrap_or(0)} ${best}")
    }
    println("malformed: ${bad}")
}

